import { PageHeader } from "../components/PageHeader";
import { SectionHeading } from "../components/SectionHeading";
import { Reveal } from "../components/Reveal";
import { Marquee } from "../components/Marquee";
import { TECHNIQUES, BOARD, IMG } from "../data/content";
import { Waves, Compass, Handshake, Leaf } from "lucide-react";

export default function About() {
  return (
    <main data-testid="about-page">
      <PageHeader
        eyebrow="Ο Σύλλογος"
        titleLines={["Από τον Αχελώο,", "για τη λιμνοθάλασσα."]}
        description="Ο Σύλλογος Επαγγελματιών Αλιέων Δήμου Μεσολογγίου «Ο Αχελώος» — γνωστός και ως Σύλλογος Μεσολογγίου – Αιτωλικού – Οινιαδών — εκπροσωπεί τους επαγγελματίες και ελεύθερους αλιείς της ευρύτερης περιοχής του Εθνικού Πάρκου Λιμνοθαλασσών."
        meta="ΕΔΡΑ: ΛΙΜΑΝΙ ΜΕΣΟΛΟΓΓΙΟΥ — ΜΕΛΗ: ΕΠΑΓΓΕΛΜΑΤΙΕΣ & ΕΛΕΥΘΕΡΟΙ ΑΛΙΕΙΣ"
      />

      <section className="py-16 sm:py-24 px-4 sm:px-8 lg:px-16" data-testid="about-history-section">
        <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
          <div className="lg:col-span-7 space-y-6 text-base sm:text-lg font-light leading-relaxed text-slate-700">
            <Reveal>
              <p>
                <strong className="font-semibold text-navy">Η ιστορία μας</strong> είναι δεμένη με τα νερά της λιμνοθάλασσας.
                Για γενιές, οι οικογένειες των ψαράδων του Μεσολογγίου ζουν από τα ιβάρια — τα φυσικά ιχθυοτροφεία που
                διαμόρφωσαν οι προσχώσεις των ποταμών Αχελώου και Ευήνου.
              </p>
            </Reveal>
            <Reveal delay={0.1}>
              <p>
                Ο σύλλογος ιδρύθηκε για να δώσει συλλογική φωνή σε αυτή την κοινότητα: να διαπραγματεύεται με το κράτος,
                να προστατεύει τον υγρότοπο από ρυπάνσεις και ασυδοσία, και να διασφαλίζει ότι η παραδοσιακή αλιεία θα
                συνεχίσει να τρέφει τις οικογένειές μας.
              </p>
            </Reveal>
            <Reveal delay={0.15}>
              <p>
                Σήμερα, η παραδοσιακή αλιεία της λιμνοθάλασσας — με τα διβάρια, τις πελάδες και το σταφνοκάρι — είναι
                επίσημα καταγεγραμμένη στο Εθνικό Ευρετήριο Άυλης Πολιτιστικής Κληρονομιάς της Ελλάδας. Για εμάς δεν είναι
                τιμητικός τίτλος: είναι καθημερινή υποχρέωση.
              </p>
            </Reveal>

            <Reveal delay={0.2}>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-6">
                {[
                  [Waves, "Διεκδίκηση", "Κινητοποιήσεις και διαπραγματεύσεις για τα επαγγελματικά μας δικαιώματα."],
                  [Leaf, "Προστασία", "Αγώνας για καθαρά νερά, υγιή ιβάρια και βιώσιμη αλιεία."],
                  [Compass, "Γνώση", "Μεταβίβαση της τεχνογνωσίας στις νεότερες γενιές αλιέων."],
                  [Handshake, "Συλλογικότητα", "Κανείς ψαράς μόνος — ένα σώμα, μία φωνή."],
                ].map(([Icon, t, d], i) => (
                  <div key={i} className="bg-white rounded-2xl p-6 border border-lagoon/15 shadow-sm" data-testid={`about-pillar-${i}`}>
                    <Icon size={22} className="text-lagoon-deep mb-3" />
                    <h4 className="font-display text-lg font-semibold text-navy mb-1.5">{t}</h4>
                    <p className="text-sm font-light text-slate-600 leading-relaxed">{d}</p>
                  </div>
                ))}
              </div>
            </Reveal>
          </div>

          <div className="lg:col-span-5 space-y-4">
            <Reveal>
              <img src={IMG.houseWater10} alt="Πελάδα στη λιμνοθάλασσα" className="w-full h-80 object-cover rounded-2xl" />
            </Reveal>
            <Reveal delay={0.12}>
              <img src={IMG.boatsPano} alt="Πανοραμική της Τουρλίδας" className="w-full h-44 object-cover rounded-2xl" />
            </Reveal>
          </div>
        </div>
      </section>

      <Marquee />

      <section className="py-16 sm:py-24 px-4 sm:px-8 lg:px-16 bg-sand/60" data-testid="techniques-section">
        <div className="max-w-7xl mx-auto">
          <SectionHeading
            eyebrow="Παραδοσιακή Αλιεία"
            title="Τα εργαλεία μιας αλιείας αιώνων"
            description="Τέσσερα στοιχεία που ορίζουν τη λιμνοθαλάσσια αλιεία — ζωντανή τεχνογνωσία, όχι μουσειακή ανάμνηση."
          />
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {TECHNIQUES.map((t, i) => (
              <Reveal key={t.title} delay={i * 0.08}>
                <article className="group bg-white rounded-2xl overflow-hidden border border-lagoon/10 shadow-sm hover:shadow-xl transition-shadow duration-500" data-testid={`technique-card-${i}`}>
                  <div className="overflow-hidden h-48">
                    <img src={t.img} alt={t.title} loading="lazy" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" />
                  </div>
                  <div className="p-6">
                    <h3 className="font-display text-2xl font-semibold text-navy mb-2">{t.title}</h3>
                    <p className="text-sm font-light text-slate-600 leading-relaxed">{t.text}</p>
                  </div>
                </article>
              </Reveal>
            ))}
          </div>
        </div>
      </section>

      <section className="py-16 sm:py-24 px-4 sm:px-8 lg:px-16" data-testid="board-section">
        <div className="max-w-7xl mx-auto">
          <SectionHeading
            eyebrow="Διοικητικό Συμβούλιο"
            title="Τα πρόσωπα του συλλόγου"
            description="Εκλεγμένο διοικητικό συμβούλιο από επαγγελματίες αλιείες της περιοχής, στη διάθεση κάθε μέλους."
          />
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {BOARD.map((m, i) => (
              <Reveal key={m.role} delay={i * 0.06}>
                <div className="flex items-center gap-4 bg-white rounded-2xl px-6 py-5 border border-lagoon/15 shadow-sm" data-testid={`board-member-${i}`}>
                  <span className="w-12 h-12 rounded-full bg-lagoon-mist text-lagoon-deep font-display font-bold text-xl flex items-center justify-center shrink-0">
                    {m.name.charAt(0)}
                  </span>
                  <div>
                    <p className="font-mono2 text-[11px] uppercase tracking-[0.2em] text-lagoon-deep font-semibold">{m.role}</p>
                    <p className="font-semibold text-navy">{m.name}</p>
                  </div>
                </div>
              </Reveal>
            ))}
          </div>
        </div>
      </section>
    </main>
  );
}
