import { Reveal, MaskLine } from "./Reveal";

export const PageHeader = ({ eyebrow, titleLines, description, meta }) => (
  <header className="relative pt-32 sm:pt-40 pb-14 sm:pb-20 px-4 sm:px-8 lg:px-16 max-w-7xl mx-auto" data-testid="page-header">
    <Reveal y={16}>
      <p className="font-mono2 text-xs sm:text-sm uppercase tracking-[0.25em] text-lagoon-deep font-semibold mb-5">
        {eyebrow}
      </p>
    </Reveal>
    <h1 className="font-display text-4xl sm:text-5xl lg:text-6xl font-bold tracking-tight leading-[1.08] text-navy">
      {titleLines.map((line, i) => (
        <MaskLine key={i} delay={0.08 + i * 0.12}>
          {line}
        </MaskLine>
      ))}
    </h1>
    {description && (
      <Reveal delay={0.3}>
        <p className="mt-6 max-w-2xl text-base sm:text-lg leading-relaxed font-light text-slate-600">
          {description}
        </p>
      </Reveal>
    )}
    {meta && (
      <Reveal delay={0.4}>
        <p className="mt-6 font-mono2 text-xs sm:text-sm text-slate-500 tracking-wider">{meta}</p>
      </Reveal>
    )}
    <div className="mt-10 h-px w-full bg-gradient-to-r from-lagoon-deep/40 via-lagoon/20 to-transparent" />
  </header>
);
