const pageUrl = () => `${window.location.origin}${process.env.PUBLIC_URL || ""}/`;

async function copyOrShare({ title, text, url }) {
  if (navigator.share) {
    try {
      await navigator.share({ title, text, url });
      toast.success("Η κοινοποίηση ολοκληρώθηκε");
      return;
    } catch (error) {
      if (error?.name === "AbortError") return;
    }
  }

  try {
    await navigator.clipboard.writeText(url);
    toast.success("Ο σύνδεσμος αντιγράφηκε");
  } catch {
    window.prompt("Αντιγράψτε τον σύνδεσμο:", url);
  }
}

