import { Link } from "react-router-dom";
import { ArrowUpRight, Fish, Shield, Users, Landmark } from "lucide-react";
import { Hero } from "../components/Hero";
import { Marquee } from "../components/Marquee";
import { SectionHeading } from "../components/SectionHeading";
import { Reveal } from "../components/Reveal";
import { CHAPTERS, STATS, NEWS, IMG } from "../data/content";

const Chapter = ({ ch, flip }) => (
  <div className={`grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-14 items-center py-14 sm:py-20 border-t border-navy/10 first:border-t-0`} data-testid={`chapter-${ch.num}`}>
    <div className={`lg:col-span-6 ${flip ? "lg:order-2" : ""}`}>
      <p className="font-mono2 text-sm text-lagoon-deep font-semibold tracking-[0.3em] mb-4">{ch.num} /</p>
      <h3 className="font-display text-2xl sm:text-3xl lg:text-4xl font-semibold text-navy tracking-tight leading-snug mb-5">
        {ch.title}
      </h3>
      <p className="text-base sm:text-lg font-light leading-relaxed text-slate-600 max-w-xl">{ch.text}</p>
    </div>
    <div className={`lg:col-span-6 ${flip ? "lg:order-1" : ""}`}>
      <Reveal>
        <figure className="relative group overflow-hidden rounded-2xl" style={{ clipPath: "inset(0 round 16px)" }}>
          <img
            src={ch.img}
            alt={ch.caption}
            loading="lazy"
            className="w-full h-72 sm:h-96 object-cover transition-transform duration-700 ease-out group-hover:scale-105"
          />
          <figcaption className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-navy/80 to-transparent px-6 pt-14 pb-5">
            <span className="font-mono2 text-xs uppercase tracking-[0.2em] text-white/85">{ch.caption}</span>
          </figcaption>
        </figure>
      </Reveal>
    </div>
  </div>
);

export default function Home() {
  const latest = NEWS.slice(0, 3);
  return (
    <main data-testid="home-page">
      <Hero />
      <Marquee />

      <section className="py-14 sm:py-20 px-4 sm:px-8 lg:px-16" data-testid="stats-section">
        <div className="max-w-7xl mx-auto grid grid-cols-2 lg:grid-cols-4 gap-6 sm:gap-10">
          {STATS.map((s, i) => (
            <Reveal key={s.label} delay={i * 0.08}>
              <div className="border-l-2 border-lagoon pl-5" data-testid={`stat-${i}`}>
                <p className="font-display text-3xl sm:text-4xl lg:text-5xl font-bold text-navy">{s.value}</p>
                <p className="mt-2 font-mono2 text-[11px] sm:text-xs uppercase tracking-[0.18em] text-slate-500">{s.label}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </section>

      <section className="py-16 sm:py-24 lg:py-28 px-4 sm:px-8 lg:px-16 bg-sand/60" data-testid="manifesto-section">
        <div className="max-w-7xl mx-auto">
          <SectionHeading
            eyebrow="Το Μανιφέστο μας"
            title="Τέσσερις λόγοι που υπάρχουμε"
            description="Από το δέλτα του Αχελώου ως τις εκβολές του Ευήνου, η λιμνοθάλασσα δεν είναι απλώς ο τόπος δουλειάς μας. Είναι το σπίτι μας — και το υπερασπιζόμαστε με τέσσερις στόχους."
          />
          <div>
            {CHAPTERS.map((ch, i) => (
              <Chapter key={ch.num} ch={ch} flip={i % 2 === 1} />
            ))}
          </div>
        </div>
      </section>

      <section className="py-16 sm:py-24 px-4 sm:px-8 lg:px-16" data-testid="ecosystem-section">
        <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-10 items-center">
          <div className="lg:col-span-5">
            <SectionHeading
              eyebrow="Το Οικοσύστημα"
              title="Ένας υγρότοπος παγκόσμιας σημασίας"
              description="Η λιμνοθάλασσα Μεσολογγίου – Αιτωλικού ανήκει στις προστατευόμενες περιοχές Natura 2000 και στη Σύμβαση Ramsar. Οι πελάδες, τα ιβάρια και το αυγοτάραχο αποτελούν ζωντανή πολιτιστική κληρονομιά."
            />
            <Reveal delay={0.2}>
              <div className="grid grid-cols-2 gap-4">
                {[
                  [Shield, "Natura 2000 & Ramsar"],
                  [Fish, "50+ είδη ψαριών"],
                  [Users, "Γενιές αλιέων"],
                  [Landmark, "Άυλη κληρονομιά"],
                ].map(([Icon, label], i) => (
                  <div key={i} className="flex items-center gap-3 bg-white rounded-xl px-4 py-3.5 border border-lagoon/15 shadow-sm">
                    <Icon size={18} className="text-lagoon-deep shrink-0" />
                    <span className="text-sm font-medium text-navy">{label}</span>
                  </div>
                ))}
              </div>
            </Reveal>
          </div>
          <div className="lg:col-span-7 grid grid-cols-2 gap-4">
            <Reveal className="col-span-2">
              <img src={IMG.lagoonAerial} alt="Λιμνοθάλασσα από ψηλά" loading="lazy" className="w-full h-56 sm:h-72 object-cover rounded-2xl" />
            </Reveal>
            <Reveal delay={0.1}>
              <img src={IMG.bird} alt="Πουλιά της λιμνοθάλασσας" loading="lazy" className="w-full h-40 sm:h-52 object-cover rounded-2xl" />
            </Reveal>
            <Reveal delay={0.18}>
              <img src={IMG.houseWater10} alt="Πελάδα στα νερά" loading="lazy" className="w-full h-40 sm:h-52 object-cover rounded-2xl" />
            </Reveal>
          </div>
        </div>
      </section>

      <Marquee dark />

      <section className="py-16 sm:py-24 px-4 sm:px-8 lg:px-16" data-testid="news-preview-section">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-end justify-between gap-6 mb-12">
            <SectionHeading eyebrow="Ενημέρωση" title="Τελευταία Νέα" />
            <Link
              to="/nea"
              data-testid="news-preview-all-link"
              className="hidden sm:inline-flex shrink-0 items-center gap-2 mb-12 rounded-full border-2 border-navy/15 text-navy text-sm font-semibold px-5 py-2.5 transition-colors duration-300 hover:border-lagoon hover:text-lagoon-deep"
            >
              Όλα τα νέα <ArrowUpRight size={16} />
            </Link>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {latest.map((n, i) => (
              <Reveal key={n.id} delay={i * 0.1}>
                <Link to="/nea" data-testid={`news-preview-card-${n.id}`} className="group block bg-white rounded-2xl overflow-hidden border border-lagoon/10 shadow-sm hover:shadow-xl transition-shadow duration-500">
                  <div className="overflow-hidden h-52">
                    <img src={n.img} alt={n.title} loading="lazy" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" />
                  </div>
                  <div className="p-6">
                    <p className="font-mono2 text-[11px] uppercase tracking-[0.2em] text-lagoon-deep font-semibold mb-3">{n.cat} — {n.date}</p>
                    <h3 className="font-display text-xl font-semibold text-navy leading-snug group-hover:text-lagoon-deep transition-colors duration-300">{n.title}</h3>
                  </div>
                </Link>
              </Reveal>
            ))}
          </div>
        </div>
      </section>

      <section className="relative py-20 sm:py-28 px-4 sm:px-8 lg:px-16 overflow-hidden" data-testid="cta-section">
        <img src={IMG.sunset2} alt="" aria-hidden="true" loading="lazy" className="absolute inset-0 w-full h-full object-cover" />
        <div className="absolute inset-0 bg-navy/70" />
        <div className="relative max-w-4xl mx-auto text-center">
          <Reveal>
            <p className="font-mono2 text-xs sm:text-sm uppercase tracking-[0.3em] text-lagoon font-semibold mb-5">Στάσου δίπλα μας</p>
            <h2 className="font-display text-3xl sm:text-4xl lg:text-5xl font-bold text-white tracking-tight leading-tight">
              Η λιμνοθάλασσα χρειάζεται φωνές.<br className="hidden sm:block" /> Η δική σου μετράει.
            </h2>
            <p className="mt-6 text-slate-200 font-light text-base sm:text-lg max-w-2xl mx-auto leading-relaxed">
              Γίνε μέλος του συλλόγου, υπογράψτε τις διεκδικήσεις μας ή απλώς έλα να γνωρίσουμε τη δουλειά μας από κοντά.
            </p>
            <div className="mt-10 flex flex-wrap justify-center gap-4">
              <Link
                to="/epikoinonia"
                data-testid="cta-contact-button"
                className="inline-flex items-center gap-2 rounded-full bg-lagoon text-white font-semibold px-8 py-4 transition-all duration-300 hover:bg-lagoon-hover hover:-translate-y-0.5"
              >
                Επικοινώνησε μαζί μας <ArrowUpRight size={18} />
              </Link>
              <Link
                to="/diamartyries"
                data-testid="cta-protests-button"
                className="inline-flex items-center gap-2 rounded-full border-2 border-white/70 text-white font-semibold px-8 py-3.5 transition-colors duration-300 hover:bg-white hover:text-navy"
              >
                Δες τις Διαμαρτυρίες
              </Link>
            </div>
          </Reveal>
        </div>
      </section>
    </main>
  );
}
