import { useMemo, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { X, ArrowUpRight, CalendarDays, Tag } from "lucide-react";
import { PageHeader } from "../components/PageHeader";
import { Reveal } from "../components/Reveal";
import { NEWS } from "../data/content";

const CATS = ["Όλα", "Δελτίο Τύπου", "Αλιευτικοί Κανονισμοί", "Οικολογία", "Εκδηλώσεις"];

export default function News() {
  const [cat, setCat] = useState("Όλα");
  const [active, setActive] = useState(null);

  const items = useMemo(
    () => NEWS.filter((n) => cat === "Όλα" || n.cat === cat),
    [cat]
  );
  const featured = items.find((n) => n.featured) || items[0];
  const rest = items.filter((n) => n !== featured);

  return (
    <main data-testid="news-page">
      <PageHeader
        eyebrow="Νέα & Ανακοινώσεις"
        titleLines={["Η φωνή του", "συλλόγου, γραπτά."]}
        description="Δελτία τύπου, αποφάσεις του Δ.Σ., αλιευτικοί κανονισμοί, οικολογικές δράσεις και εκδηλώσεις — όλα όσα αφορούν τους αλιείς της λιμνοθάλασσας."
        meta={`${NEWS.length} ΑΝΑΡΤΗΣΕΙΣ — ΕΝΗΜΕΡΩΣΗ ΙΟΥΝΙΟΣ 2026`}
      />

      <section className="pb-20 px-4 sm:px-8 lg:px-16 max-w-7xl mx-auto">
        <div className="flex flex-wrap gap-2.5 mb-12" data-testid="news-filters">
          {CATS.map((c) => (
            <button
              key={c}
              onClick={() => setCat(c)}
              data-testid={`news-filter-${c === "Όλα" ? "all" : c}`}
              className={`rounded-full px-5 py-2.5 text-sm font-semibold transition-colors duration-300 border-2 ${
                cat === c
                  ? "bg-navy text-white border-navy"
                  : "bg-white text-slate-600 border-lagoon/20 hover:border-lagoon hover:text-lagoon-deep"
              }`}
            >
              {c}
            </button>
          ))}
        </div>

        {featured && (
          <Reveal>
            <button
              onClick={() => setActive(featured)}
              data-testid="news-featured-card"
              className="group w-full text-left grid grid-cols-1 lg:grid-cols-2 bg-white rounded-3xl overflow-hidden border border-lagoon/15 shadow-sm hover:shadow-2xl transition-shadow duration-500 mb-10"
            >
              <div className="overflow-hidden h-72 lg:h-auto">
                <img src={featured.img} alt={featured.title} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" />
              </div>
              <div className="p-8 lg:p-12 flex flex-col justify-center">
                <p className="font-mono2 text-xs uppercase tracking-[0.25em] text-lagoon-deep font-semibold mb-4 flex items-center gap-3">
                  <Tag size={13} /> {featured.cat}
                </p>
                <h2 className="font-display text-2xl sm:text-3xl lg:text-4xl font-semibold text-navy leading-snug group-hover:text-lagoon-deep transition-colors duration-300">
                  {featured.title}
                </h2>
                <p className="mt-4 text-slate-600 font-light leading-relaxed">{featured.excerpt}</p>
                <span className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-lagoon-deep">
                  Διαβάστε ολόκληρο <ArrowUpRight size={16} className="transition-transform duration-300 group-hover:translate-x-1 group-hover:-translate-y-1" />
                </span>
                <p className="mt-5 font-mono2 text-xs text-slate-400 flex items-center gap-2">
                  <CalendarDays size={13} /> {featured.date}
                </p>
              </div>
            </button>
          </Reveal>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {rest.map((n, i) => (
            <Reveal key={n.id} delay={i * 0.07}>
              <button
                onClick={() => setActive(n)}
                data-testid={`news-card-${n.id}`}
                className="group w-full h-full text-left bg-white rounded-2xl overflow-hidden border border-lagoon/10 shadow-sm hover:shadow-xl transition-shadow duration-500 flex flex-col"
              >
                <div className="overflow-hidden h-52 shrink-0">
                  <img src={n.img} alt={n.title} loading="lazy" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" />
                </div>
                <div className="p-6 flex flex-col flex-1">
                  <p className="font-mono2 text-[11px] uppercase tracking-[0.2em] text-lagoon-deep font-semibold mb-3">{n.cat} — {n.date}</p>
                  <h3 className="font-display text-xl font-semibold text-navy leading-snug group-hover:text-lagoon-deep transition-colors duration-300">{n.title}</h3>
                  <p className="mt-3 text-sm font-light text-slate-600 leading-relaxed flex-1">{n.excerpt}</p>
                  <span className="mt-4 inline-flex items-center gap-1.5 text-sm font-semibold text-lagoon-deep">
                    Περισσότερα <ArrowUpRight size={15} />
                  </span>
                </div>
              </button>
            </Reveal>
          ))}
        </div>
      </section>

      <AnimatePresence>
        {active && (
          <motion.div
            className="fixed inset-0 z-[70] flex items-end sm:items-center justify-center p-0 sm:p-6"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            data-testid="news-article-modal"
          >
            <div className="absolute inset-0 bg-navy/60 backdrop-blur-sm" onClick={() => setActive(null)} />
            <motion.article
              initial={{ y: 60, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: 60, opacity: 0 }}
              transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}
              className="relative bg-white w-full max-w-3xl max-h-[88vh] overflow-y-auto rounded-t-3xl sm:rounded-3xl shadow-2xl"
            >
              <div className="relative h-64 sm:h-80 shrink-0">
                <img src={active.img} alt={active.title} className="w-full h-full object-cover" />
                <button
                  onClick={() => setActive(null)}
                  data-testid="news-article-close-button"
                  className="absolute top-4 right-4 w-11 h-11 rounded-full bg-white/90 backdrop-blur flex items-center justify-center text-navy hover:bg-lagoon hover:text-white transition-colors duration-300"
                  aria-label="Κλείσιμο"
                >
                  <X size={20} />
                </button>
              </div>
              <div className="p-8 sm:p-10">
                <p className="font-mono2 text-xs uppercase tracking-[0.25em] text-lagoon-deep font-semibold mb-4">
                  {active.cat} — {active.date}
                </p>
                <h2 className="font-display text-2xl sm:text-3xl font-semibold text-navy leading-snug mb-6">{active.title}</h2>
                <div className="space-y-4 text-base font-light text-slate-700 leading-relaxed">
                  {active.body.split("\n\n").map((p, i) => (
                    <p key={i}>{p}</p>
                  ))}
                </div>
              </div>
            </motion.article>
          </motion.div>
        )}
      </AnimatePresence>
    </main>
  );
}
