import { MARQUEE_ITEMS } from "../data/content";
import { Anchor } from "lucide-react";

export const Marquee = ({ dark = false }) => {
  const items = [...MARQUEE_ITEMS, ...MARQUEE_ITEMS];
  return (
    <div
      className={`overflow-hidden py-5 border-y marquee-paused ${
        dark ? "bg-navy border-white/10" : "bg-lagoon-mist border-lagoon/15"
      }`}
      data-testid="editorial-marquee"
      aria-hidden="true"
    >
      <div className="animate-marquee flex w-max items-center gap-10">
        {items.map((item, i) => (
          <span key={i} className="flex items-center gap-10 shrink-0">
            <span
              className={`font-mono2 text-xs sm:text-sm uppercase tracking-[0.3em] font-medium whitespace-nowrap ${
                dark ? "text-white/60" : "text-lagoon-deep"
              }`}
            >
              {item}
            </span>
            <Anchor size={13} className={dark ? "text-lagoon" : "text-lagoon/60"} />
          </span>
        ))}
      </div>
    </div>
  );
};
