import { useRef } from "react";
import { Link } from "react-router-dom";
import { motion, useScroll, useTransform } from "framer-motion";
import { ArrowDown, ArrowUpRight } from "lucide-react";
import { IMG } from "../data/content";
import { MaskLine } from "./Reveal";

export const Hero = () => {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start start", "end start"] });
  const bgY = useTransform(scrollYProgress, [0, 1], ["0%", "22%"]);
  const bgScale = useTransform(scrollYProgress, [0, 1], [1.05, 1.18]);
  const fade = useTransform(scrollYProgress, [0, 0.7], [1, 0]);

  return (
    <section ref={ref} className="relative min-h-[100svh] flex flex-col overflow-hidden" data-testid="hero-section">
      <motion.div className="absolute inset-0" style={{ y: bgY, scale: bgScale }}>
        <img
          src={IMG.hero}
          alt="Ηλιοβασίλεμα στη λιμνοθάλασσα του Μεσολογγίου"
          className="w-full h-full object-cover"
          data-testid="hero-background-image"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-aegean via-aegean/35 to-aegean/10" />
        <div className="absolute inset-0 bg-gradient-to-r from-aegean/70 via-transparent to-transparent" />
      </motion.div>

      <motion.div
        style={{ opacity: fade }}
        className="relative z-10 flex-1 flex flex-col justify-center max-w-7xl mx-auto w-full px-4 sm:px-8 lg:px-16 pt-28 pb-40"
      >
        <motion.p
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.25, duration: 0.7 }}
          className="font-mono2 text-xs sm:text-sm uppercase tracking-[0.3em] text-lagoon-deep font-semibold mb-6"
          data-testid="hero-eyebrow"
        >
          Σύλλογος Επαγγελματιών Αλιέων — Δήμος Μεσολογγίου
        </motion.p>

        <h1 className="font-display font-bold tracking-tight leading-[1.02] text-navy text-4xl sm:text-5xl lg:text-6xl max-w-4xl" data-testid="hero-title">
          <MaskLine delay={0.35}>Η λιμνοθάλασσα</MaskLine>
          <MaskLine delay={0.5}>
            είναι <em className="not-italic text-lagoon-deep">η ζωή</em> μας.
          </MaskLine>
        </h1>

        <motion.p
          initial={{ opacity: 0, y: 18 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.85, duration: 0.7 }}
          className="mt-7 max-w-xl text-base sm:text-lg font-light leading-relaxed text-slate-700"
          data-testid="hero-subtitle"
        >
          Ο σύλλογος «Ο Αχελώος» ενώνει τους επαγγελματίες ψαράδες του Μεσολογγίου, του Αιτωλικού
          και των Οινιαδών. Προστατεύουμε τον υγρότοπο, διεκδικούμε τα δικαιώματά μας και κρατάμε
          ζωντανή την παραδοσιακή αλιεία.
        </motion.p>

        <motion.div
          initial={{ opacity: 0, y: 18 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 1.05, duration: 0.7 }}
          className="mt-10 flex flex-wrap items-center gap-4"
        >
          <Link
            to="/yliko"
            data-testid="hero-media-button"
            className="inline-flex items-center gap-2 rounded-full bg-lagoon text-white font-semibold text-sm sm:text-base px-7 py-3.5 transition-all duration-300 hover:bg-lagoon-hover hover:-translate-y-0.5 shadow-lg shadow-lagoon/25"
          >
            Δες το Υλικό <ArrowUpRight size={18} />
          </Link>
          <Link
            to="/diamartyries"
            data-testid="hero-protests-button"
            className="inline-flex items-center gap-2 rounded-full border-2 border-navy/80 text-navy font-semibold text-sm sm:text-base px-7 py-3 transition-colors duration-300 hover:bg-navy hover:text-white"
          >
            Οι Διεκδικήσεις μας
          </Link>
        </motion.div>
      </motion.div>

      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1.3, duration: 0.8 }}
        className="absolute bottom-0 inset-x-0 z-10 border-t border-navy/10 bg-white/70 backdrop-blur-md"
        data-testid="hero-meta-bar"
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-8 lg:px-16 py-4 flex items-center justify-between gap-6">
          <div className="flex items-center gap-6 sm:gap-10 overflow-hidden">
            <span className="font-mono2 text-[10px] sm:text-xs uppercase tracking-[0.2em] text-slate-600 whitespace-nowrap">
              38°22′N — 21°25′E
            </span>
            <span className="hidden sm:inline font-mono2 text-xs uppercase tracking-[0.2em] text-slate-600 whitespace-nowrap">
              Εθνικό Πάρκο Λιμνοθαλασσών
            </span>
            <span className="hidden md:inline font-mono2 text-xs uppercase tracking-[0.2em] text-slate-600 whitespace-nowrap">
              Αχελώος · Ευήνος
            </span>
          </div>
          <span className="animate-float-slow text-lagoon-deep" data-testid="hero-scroll-indicator">
            <ArrowDown size={20} />
          </span>
        </div>
      </motion.div>
    </section>
  );
};
