import { useEffect } from "react";
import { BrowserRouter, Routes, Route, useLocation } from "react-router-dom";
import Lenis from "lenis";
import { Toaster } from "sonner";
import { Navbar } from "@/components/Navbar";
import { Footer } from "@/components/Footer";
import Home from "@/pages/Home";
import About from "@/pages/About";
import News from "@/pages/News";
import Protests from "@/pages/Protests";
import Media from "@/pages/Media";
import Contact from "@/pages/Contact";
import Press from "@/pages/Press";

const ScrollManager = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: "instant" });
  }, [pathname]);
  return null;
};

const useLenis = () => {
  useEffect(() => {
    const lenis = new Lenis({ duration: 1.15, smoothWheel: true });
    let rafId;
    const raf = (time) => {
      lenis.raf(time);
      rafId = requestAnimationFrame(raf);
    };
    rafId = requestAnimationFrame(raf);
    return () => {
      cancelAnimationFrame(rafId);
      lenis.destroy();
    };
  }, []);
};

function Shell() {
  useLenis();
  return (
    <>
      <div className="grain-overlay" aria-hidden="true" />
      <ScrollManager />
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/syllogos" element={<About />} />
        <Route path="/nea" element={<News />} />
        <Route path="/deltia-typou" element={<Press />} />
        <Route path="/diamartyries" element={<Protests />} />
        <Route path="/yliko" element={<Media />} />
        <Route path="/epikoinonia" element={<Contact />} />
        <Route path="*" element={<Home />} />
      </Routes>
      <Footer />
      <Toaster position="bottom-right" richColors closeButton />
    </>
  );
}

function App() {
  return (
    <BrowserRouter basename={process.env.PUBLIC_URL || "/"}>
      <Shell />
    </BrowserRouter>
  );
}

export default App;
