import { Reveal, MaskLine } from "./Reveal";

export const SectionHeading = ({ eyebrow, title, description, align = "left", light = false }) => (
  <div className={`mb-12 sm:mb-16 ${align === "center" ? "text-center" : "text-left"}`} data-testid="section-heading">
    {eyebrow && (
      <Reveal y={16}>
        <p className={`font-mono2 text-xs sm:text-sm uppercase tracking-[0.25em] font-semibold mb-4 ${light ? "text-lagoon" : "text-lagoon-deep"}`}>
          {eyebrow}
        </p>
      </Reveal>
    )}
    <h2 className={`font-display text-2xl sm:text-3xl lg:text-4xl font-semibold tracking-tight leading-snug ${light ? "text-white" : "text-navy"}`}>
      <MaskLine delay={0.05}>{title}</MaskLine>
    </h2>
    {description && (
      <Reveal delay={0.15}>
        <p className={`mt-5 max-w-2xl text-base sm:text-lg leading-relaxed font-light ${light ? "text-slate-300" : "text-slate-600"} ${align === "center" ? "mx-auto" : ""}`}>
          {description}
        </p>
      </Reveal>
    )}
  </div>
);
