import { useState } from "react";
import { toast } from "sonner";
import { PageHeader } from "../components/PageHeader";
import { SectionHeading } from "../components/SectionHeading";
import { Reveal } from "../components/Reveal";
import { PROTESTS, IMG, CONTACT } from "../data/content";
import { Megaphone, FileText, PenLine, Phone } from "lucide-react";

export default function Protests() {
  const [form, setForm] = useState({ name: "", email: "", message: "" });

  const submit = (e) => {
    e.preventDefault();
    if (!form.name.trim() || !/^\S+@\S+\.\S+$/.test(form.email)) {
      toast.error("Συμπληρώστε ονοματεπώνυμο και έγκυρο email.");
      return;
    }
    toast.success("Η υποστήριξή σας καταγράφηκε. Ευχαριστούμε που στέκεστε δίπλα μας!");
    setForm({ name: "", email: "", message: "" });
  };

  return (
    <main data-testid="protests-page">
      <PageHeader
        eyebrow="Διαμαρτυρίες & Κινητοποιήσεις"
        titleLines={["Όταν η θάλασσα", "πνίγεται, φωνάζουμε."]}
        description="Χρονολόγιο των διεκδικήσεων μας: συσκέψεις, συλλαλητήρια, απεργιακές αποχές και ψηφίσματα. Κάθε κινητοποίηση είναι ένα κύμα — και τα κύματα δεν σταματούν."
        meta="2018 — ΣΗΜΕΡΑ · ΣΥΝΕΧΙΣΤΗΣ ΚΑΤΑΓΡΑΦΗ"
      />

      <section className="pb-20 px-4 sm:px-8 lg:px-16 max-w-5xl mx-auto" data-testid="protests-timeline-section">
        <div className="relative">
          <div className="absolute left-5 sm:left-1/2 top-0 bottom-0 w-px bg-lagoon/30 sm:-translate-x-1/2" />
          <div className="space-y-12">
            {PROTESTS.map((p, i) => (
              <Reveal key={p.title} delay={0.05}>
                <div className={`relative flex flex-col sm:flex-row gap-6 sm:gap-0 ${i % 2 === 0 ? "" : "sm:flex-row-reverse"}`} data-testid={`protest-item-${i}`}>
                  <div className="hidden sm:block sm:w-1/2" />
                  <div className="absolute left-5 sm:left-1/2 top-2 w-3.5 h-3.5 rounded-full bg-lagoon border-4 border-aegean sm:-translate-x-1/2 z-10" />
                  <div className={`sm:w-1/2 pl-12 sm:pl-0 ${i % 2 === 0 ? "sm:pl-14" : "sm:pr-14 sm:text-right"}`}>
                    <p className="font-mono2 text-xs uppercase tracking-[0.25em] text-lagoon-deep font-semibold mb-2">
                      {p.date} · {p.tag}
                    </p>
                    <h3 className="font-display text-2xl font-semibold text-navy leading-snug mb-3">{p.title}</h3>
                    <p className="text-base font-light text-slate-600 leading-relaxed">{p.desc}</p>
                  </div>
                </div>
              </Reveal>
            ))}
          </div>
        </div>
      </section>

      <section className="py-16 sm:py-24 px-4 sm:px-8 lg:px-16 bg-navy text-white relative overflow-hidden" data-testid="resolution-section">
        <img src={IMG.protest} alt="" aria-hidden="true" loading="lazy" className="absolute inset-0 w-full h-full object-cover opacity-15" />
        <div className="relative max-w-4xl mx-auto">
          <SectionHeading
            light
            eyebrow="Απόσπασμα ψηφίσματος"
            title="«Η λιμνοθάλασσα δεν πωλείται, δεν παραχωρείται, δεν εγκαταλείπεται.»"
          />
          <Reveal>
            <div className="bg-white/5 border border-white/10 rounded-2xl p-8 sm:p-10 backdrop-blur-sm">
              <FileText size={26} className="text-lagoon mb-6" />
              <div className="space-y-4 text-slate-200 font-light leading-relaxed text-base sm:text-lg">
                <p>
                  Διεκδικούμε την αναγνώριση της ιδιαιτερότητας της λιμνοθαλάσσιας αλιείας Μεσολογγίου – Αιτωλικού ως
                  παραδοσιακής δραστηριότητας εθνικής πολιτιστικής σημασίας.
                </p>
                <p>
                  Απαιτούμε τη συμμετοχή του συλλόγου σε κάθε συμβουλευτικό όργανο που λαμβάνει αποφάσεις για τον υγρότοπο,
                  καθώς και οικονομικές αντισταθμίσεις για τις περιόδους απαγόρευσης της αλιείας.
                </p>
                <p>
                  Καταγγέλλουμε κάθε σχέδιο εμπορευματοποίησης των ιβαρίων και παραχώρησης δημόσιας θαλάσσιας έκτασης σε
                  ιδιωτικά συμφέροντα.
                </p>
              </div>
              <p className="mt-8 font-mono2 text-xs uppercase tracking-[0.25em] text-lagoon">
                Το Διοικητικό Συμβούλιο — Μεσολόγγι, 2026
              </p>
            </div>
          </Reveal>
        </div>
      </section>

      <section className="py-16 sm:py-24 px-4 sm:px-8 lg:px-16" data-testid="support-section">
        <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-12">
          <div>
            <SectionHeading
              eyebrow="Ψήφισμα υποστήριξης"
              title="Υπογράψτε τη διεκδίκησή μας"
              description="Κάθε υπογραφή δυναμώνει τη φωνή μας στα υπουργεία και στους φορείς. Συμπληρώστε τη δήλωση υποστήριξης — θα σας ενημερώνουμε για κάθε κινητοποίηση."
            />
            <Reveal delay={0.15}>
              <div className="space-y-4">
                <div className="flex items-start gap-4 bg-lagoon-mist rounded-2xl p-5 border border-lagoon/20">
                  <Megaphone size={20} className="text-lagoon-deep mt-0.5 shrink-0" />
                  <p className="text-sm font-light text-slate-700 leading-relaxed">
                    Για τον Τύπο και τα ΜΜΕ: {CONTACT.email} — {CONTACT.phone}
                  </p>
                </div>
                <div className="flex items-start gap-4 bg-lagoon-mist rounded-2xl p-5 border border-lagoon/20">
                  <Phone size={20} className="text-lagoon-deep mt-0.5 shrink-0" />
                  <p className="text-sm font-light text-slate-700 leading-relaxed">
                    Επόμενη ανοιχτή σύσκεψη: κάθε πρώτη Τετάρτη του μήνα, 19:00, στα γραφεία του συλλόγου στο λιμάνι.
                  </p>
                </div>
              </div>
            </Reveal>
          </div>

          <Reveal delay={0.1}>
            <form onSubmit={submit} className="bg-white rounded-3xl border border-lagoon/15 shadow-lg p-8 sm:p-10" data-testid="support-form">
              <label className="block mb-5">
                <span className="font-mono2 text-xs uppercase tracking-[0.2em] text-slate-500 font-semibold">Ονοματεπώνυμο *</span>
                <input
                  type="text"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  data-testid="support-name-input"
                  placeholder="π.χ. Γιώργος Αλιέας"
                  className="mt-2 w-full rounded-xl border-2 border-lagoon/20 bg-aegean px-4 py-3 text-navy outline-none focus:border-lagoon transition-colors duration-300"
                />
              </label>
              <label className="block mb-5">
                <span className="font-mono2 text-xs uppercase tracking-[0.2em] text-slate-500 font-semibold">Email *</span>
                <input
                  type="email"
                  value={form.email}
                  onChange={(e) => setForm({ ...form, email: e.target.value })}
                  data-testid="support-email-input"
                  placeholder="you@example.gr"
                  className="mt-2 w-full rounded-xl border-2 border-lagoon/20 bg-aegean px-4 py-3 text-navy outline-none focus:border-lagoon transition-colors duration-300"
                />
              </label>
              <label className="block mb-7">
                <span className="font-mono2 text-xs uppercase tracking-[0.2em] text-slate-500 font-semibold">Σχόλιο (προαιρετικό)</span>
                <textarea
                  rows={3}
                  value={form.message}
                  onChange={(e) => setForm({ ...form, message: e.target.value })}
                  data-testid="support-message-input"
                  placeholder="Γιατί στηρίζετε τους ψαράδες της λιμνοθάλασσας;"
                  className="mt-2 w-full rounded-xl border-2 border-lagoon/20 bg-aegean px-4 py-3 text-navy outline-none focus:border-lagoon transition-colors duration-300 resize-none"
                />
              </label>
              <button
                type="submit"
                data-testid="support-submit-button"
                className="w-full inline-flex items-center justify-center gap-2 rounded-full bg-lagoon text-white font-semibold px-8 py-4 transition-all duration-300 hover:bg-lagoon-hover hover:-translate-y-0.5 shadow-lg shadow-lagoon/25"
              >
                <PenLine size={18} /> Υπογράφω τη Διεκδίκηση
              </button>
            </form>
          </Reveal>
        </div>
      </section>
    </main>
  );
}
