import { Link } from "react-router-dom";
import { Waves, MapPin, Phone, Mail, ArrowUpRight } from "lucide-react";
import { CONTACT } from "../data/content";

export const Footer = () => (
  <footer className="bg-navy text-white mt-0" data-testid="main-footer">
    <div className="max-w-7xl mx-auto px-4 sm:px-8 lg:px-16 py-16 sm:py-20">
      <div className="grid grid-cols-1 md:grid-cols-12 gap-10">
        <div className="md:col-span-5">
          <div className="flex items-center gap-3 mb-5">
            <span className="w-10 h-10 rounded-full bg-lagoon flex items-center justify-center">
              <Waves size={20} />
            </span>
            <span className="font-display font-bold text-2xl">«Ο Αχελώος»</span>
          </div>
          <p className="text-slate-300 font-light leading-relaxed max-w-sm text-sm sm:text-base">
            Σύλλογος Επαγγελματιών Αλιέων Δήμου Μεσολογγίου. Υπερασπιζόμαστε τη λιμνοθάλασσα,
            την παράδοση και τα δικαιώματα των ψαράδων μας — από τον Αχελώο ως τον Ευήνο.
          </p>
          <p className="mt-6 font-mono2 text-xs uppercase tracking-[0.2em] text-lagoon">
            {CONTACT.coords} — Λιμνοθάλασσα Μεσολογγίου
          </p>
        </div>

        <div className="md:col-span-3">
          <h4 className="font-mono2 text-xs uppercase tracking-[0.25em] text-white/50 mb-5">Πλοήγηση</h4>
          <ul className="space-y-3 text-sm">
            {[
              ["/", "Αρχική"],
              ["/syllogos", "Ο Σύλλογος"],
              ["/nea", "Νέα & Ανακοινώσεις"],
              ["/deltia-typou", "Δελτία Τύπου & Δημοσιεύσεις"],
              ["/diamartyries", "Διαμαρτυρίες"],
              ["/yliko", "Υλικό — Φωτο & Βίντεο"],
              ["/epikoinonia", "Επικοινωνία"],
            ].map(([to, label]) => (
              <li key={to}>
                <Link
                  to={to}
                  data-testid={`footer-link-${to === "/" ? "home" : to.slice(1)}`}
                  className="inline-flex items-center gap-1 text-slate-300 hover:text-lagoon transition-colors duration-300"
                >
                  {label} <ArrowUpRight size={13} className="opacity-50" />
                </Link>
              </li>
            ))}
          </ul>
        </div>

        <div className="md:col-span-4">
          <h4 className="font-mono2 text-xs uppercase tracking-[0.25em] text-white/50 mb-5">Επικοινωνία</h4>
          <ul className="space-y-4 text-sm text-slate-300">
            <li className="flex items-start gap-3">
              <MapPin size={16} className="text-lagoon mt-0.5 shrink-0" /> {CONTACT.address}
            </li>
            <li className="flex items-start gap-3">
              <Phone size={16} className="text-lagoon mt-0.5 shrink-0" /> {CONTACT.phone}
            </li>
            <li className="flex items-start gap-3">
              <Mail size={16} className="text-lagoon mt-0.5 shrink-0" /> {CONTACT.email}
            </li>
          </ul>
        </div>
      </div>

      <div className="mt-14 pt-8 border-t border-white/10 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <p className="font-mono2 text-xs text-white/40 tracking-wider">
          © 2026 Σύλλογος Επαγγ. Αλιέων Δήμου Μεσολογγίου «Ο Αχελώος»
        </p>
        <p className="font-mono2 text-xs text-white/40 tracking-wider">
          Φωτογραφίες: Wikimedia Commons · Pexels · Unsplash
        </p>
      </div>
    </div>
  </footer>
);
